import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {any} [textContent]
 * @property {any} [intent]
 * @property {Object} [colors]
 * @property {Array} [cinematicPrimitives]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * Create a journal card label node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container – position/rotation/scale will be applied by the adapter.
  const root = new Group();

  // -------------------------------------------------------------------------
  // Plane (textured background)
  // -------------------------------------------------------------------------
  // Preserve image aspect (512x320 ≈ 1.6)
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  const material = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'), // surface fallback
    map: null,
    // subtle grain could be emulated via a tiny noise node but omitted to keep
    // within allowed shader node usage; using the brushed‑metal texture instead.
  });

  // Async texture load – material updated when ready.
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const plane = new Mesh(geometry, material);
  // Center the plane; adapter positions the whole root.
  root.add(plane);

  // -------------------------------------------------------------------------
  // Text label (headline)
  // -------------------------------------------------------------------------
  const textItems =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textObjects = [];

  for (const item of textItems) {
    // Expected shape: { text: string, role?: string, typography?: { fontSize?: number } }
    const fontSize = item.typography?.fontSize ?? 39; // px fallback per spec
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: config.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Raise slightly above the plane to avoid z‑fighting.
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // -------------------------------------------------------------------------
  // Cinematic primitives (none in this spec, but process if present)
  // -------------------------------------------------------------------------
  const primitiveHandles = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name](
        root,
        prim.params ?? {}
      );
      primitiveHandles.push(handler);
    }
  }

  // -------------------------------------------------------------------------
  // UserData – handlers & cleanup
  // -------------------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose texture and material
    if (material.map) material.map.dispose();
    material.dispose();

    // Dispose geometry
    geometry.dispose();

    // Dispose any text objects (they may hold geometries/materials)
    for (const txt of textObjects) {
      txt.traverse((node) => {
        if (node.geometry) node.geometry.dispose();
        if (node.material) node.material.dispose();
      });
    }

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    }

    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return root;
}
